export class Extension {
    #id;
    #version;
    #name;
    #path;
    #enabled;
    constructor(id, version, name, path, enabled) {
        if (!id || !version) {
            throw new Error('Extension ID and version are required');
        }
        this.#id = id;
        this.#version = version;
        this.#name = name;
        this.#path = path;
        this.#enabled = enabled;
    }
    get enabled() {
        return this.#enabled;
    }
    get path() {
        return this.#path;
    }
    get version() {
        return this.#version;
    }
    get name() {
        return this.#name;
    }
    get id() {
        return this.#id;
    }
}